/**
 * T3 — playback of the original's three sound effects.
 *
 * The MIDlet's sounds are Nokia OTT tone sequences (`new Sound(bytes, FORMAT_TONE)`),
 * i.e. a handful of square-wave beeps, not samples. `tools/decode-ott.ts` turns them
 * into `assets/audio/<id>.json` note lists; this module schedules those notes on
 * WebAudio oscillators. See docs/ORIGINAL.md for the format and the parity check.
 *
 *   const audio = new AudioPlayer();
 *   await audio.load();          // fetches the three tone files
 *   audio.play('pop');           // no-op until the first user gesture unlocks WebAudio
 */

export type ToneNote = {
  note: string;
  octave?: number;
  midi?: number;
  freq?: number;
  startMs: number;
  durationMs: number;
  gateMs: number;
  velocity: number;
};

export type Tone = {
  id: string;
  source: string;
  tempoBpm: number;
  style: 'natural' | 'continuous' | 'staccato';
  durationMs: number;
  notes: ToneNote[];
};

export type SoundId = 'pop' | 'pickup' | 'up';

export const SOUND_IDS: readonly SoundId[] = ['pop', 'pickup', 'up'];

/**
 * The handset's buzzer is a square wave; `square` is the closest WebAudio gets without
 * a custom wavetable, and it keeps the effects recognisable against the T1 recording.
 */
const WAVEFORM: OscillatorType = 'square';

/** Master trim. A raw square at full scale is painfully loud through headphones. */
const MASTER_GAIN = 0.18;

/** Envelope ramps, in seconds — short enough to stay percussive, long enough not to click. */
const ATTACK = 0.004;
const RELEASE = 0.012;

const AUDIO_BASE = 'audio';

export class AudioPlayer {
  private context: AudioContext | null = null;

  private master: GainNode | null = null;

  private readonly tones = new Map<SoundId, Tone>();

  private muted = false;

  private unlockBound: (() => void) | null = null;

  /** Fetch the decoded tone tables. Safe to call before any user gesture. */
  async load(ids: readonly SoundId[] = SOUND_IDS): Promise<void> {
    await Promise.all(
      ids.map(async (id) => {
        const response = await fetch(`${AUDIO_BASE}/${id}.json`);
        if (!response.ok) throw new Error(`cannot load tone "${id}": HTTP ${response.status}`);
        this.tones.set(id, (await response.json()) as Tone);
      }),
    );
  }

  /**
   * Browsers only allow an `AudioContext` to start inside a user gesture, so listen for
   * the first one. Call once during boot; it detaches itself.
   */
  installUnlockListeners(target: EventTarget = window): void {
    if (this.unlockBound) return;
    const events = ['pointerdown', 'keydown', 'touchend'] as const;
    const unlock = (): void => {
      void this.unlock();
      for (const type of events) target.removeEventListener(type, unlock);
      this.unlockBound = null;
    };
    this.unlockBound = unlock;
    for (const type of events) target.addEventListener(type, unlock, { passive: true });
  }

  /** Create/resume the context. Must be called from a user gesture on iOS Safari. */
  async unlock(): Promise<void> {
    if (!this.context) {
      const Ctor: typeof AudioContext =
        window.AudioContext ??
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) return; // no WebAudio: stay silent rather than throw
      this.context = new Ctor();
      this.master = this.context.createGain();
      this.master.gain.value = this.muted ? 0 : MASTER_GAIN;
      this.master.connect(this.context.destination);
    }
    if (this.context.state === 'suspended') await this.context.resume();
  }

  /**
   * T12 — stop the clock on the audio hardware too. A suspended context keeps whatever is
   * already scheduled and resumes it on the way back, so a `pop` that started as the tab
   * went away finishes when it comes back rather than being cut off. Safe before the
   * unlock, where there is no context to suspend.
   */
  async suspend(): Promise<void> {
    if (this.context?.state === 'running') await this.context.suspend();
  }

  /** The other half of `suspend()`. Does not unlock: a resume is not a user gesture. */
  async resume(): Promise<void> {
    if (this.context?.state === 'suspended') await this.context.resume();
  }

  get unlocked(): boolean {
    return this.context !== null && this.context.state === 'running';
  }

  get isMuted(): boolean {
    return this.muted;
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (this.master) this.master.gain.value = muted ? 0 : MASTER_GAIN;
  }

  toggleMute(): boolean {
    this.setMuted(!this.muted);
    return this.muted;
  }

  /**
   * Fire one effect. Silently does nothing before the audio unlock or when muted, which
   * is what the game wants — sound is never load-bearing.
   */
  play(id: SoundId): void {
    const tone = this.tones.get(id);
    const context = this.context;
    const master = this.master;
    if (!tone || !context || !master || this.muted || context.state !== 'running') return;

    const start = context.currentTime;
    for (const note of tone.notes) {
      if (note.freq === undefined || note.gateMs <= 0) continue; // a rest

      const at = start + note.startMs / 1000;
      const until = at + note.gateMs / 1000;
      const peak = note.velocity / 127; // the master node applies the overall trim

      const gain = context.createGain();
      gain.gain.setValueAtTime(0, at);
      gain.gain.linearRampToValueAtTime(peak, at + ATTACK);
      gain.gain.setValueAtTime(peak, Math.max(at + ATTACK, until - RELEASE));
      gain.gain.linearRampToValueAtTime(0, until);
      gain.connect(master);

      const osc = context.createOscillator();
      osc.type = WAVEFORM;
      osc.frequency.setValueAtTime(note.freq, at);
      osc.connect(gain);
      osc.start(at);
      osc.stop(until + RELEASE);
      osc.onended = () => {
        osc.disconnect();
        gain.disconnect();
      };
    }
  }

  /** The decoded table, for debug pages and tests. */
  tone(id: SoundId): Tone | undefined {
    return this.tones.get(id);
  }
}
